import {WEAPON_ORDER} from './weapon-order.js';
import {WEAPON_SLOTS,SLOT_LABELS,attachment,weaponStats,previewBuild,effectLines,gameplayCount,EQUIPMENT} from './loadout.js';
import {WEAPON_SILHOUETTES as paths} from './weapon-icons.js';
export function gunIcon(g){return `<svg class="gun-icon" viewBox="0 0 110 75" aria-hidden="true"><path d="${paths[g]}" fill="currentColor" fill-rule="evenodd"/></svg>`}
export function reticleIcon(type){return `<svg class="reticle-icon" viewBox="0 0 60 60" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5">${type==='dot'?'<circle cx="30" cy="30" r="2" fill="currentColor"/>':type==='ring'?'<circle cx="30" cy="30" r="13"/><circle cx="30" cy="30" r="1.5" fill="currentColor"/>':type==='holo'?'<circle cx="30" cy="30" r="12"/><path d="M30 12v7m0 22v7M12 30h7m22 0h7"/><circle cx="30" cy="30" r="1"/>':type==='chevron'?'<path d="m23 34 7-8 7 8M30 37v7"/>':type==='duplex'?'<path d="M30 7v15m0 16v15M7 30h15m16 0h15" stroke-width="3"/><path d="M30 21v18M21 30h18" stroke-width=".7"/>':'<path d="M30 9v16m0 10v16M9 30h16m10 0h16"/><circle cx="30" cy="30" r="2"/>'}</svg>`}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isInteger(n)?String(n):Number(n.toFixed(n>0&&n<.1?4:2)).toString();
export function firingLabel(w){return w.charge?'CHARGE '+w.charge.toFixed(2)+'s':w.mode==='burst'?w.burst+'-ROUND BURST':w.mode==='auto'?'AUTOMATIC':'SEMI-AUTO'}
export function statsHTML(base,g,builds,preview=builds,perks={}){
 const a=weaponStats(base,g,builds),w=weaponStats(base,g,preview),near=w.falloff?.near||1,damage=w.damage*w.pellets*near+w.splash,cycle=w.interval,burst=w.burst||1,cartridges=w.volley*burst,loaded=Math.ceil(w.mag/cartridges),shots=Math.ceil(w.mag/w.volley),tail=(shots-1)%burst,lastStart=Math.floor((shots-1)/burst)*cycle,last=w.charge+lastStart+tail*w.burstGap,recovery=Math.max(0,cycle-w.charge-tail*w.burstGap),reload=(w.feedMode==='coupled'?(w.quickReload+w.reload)/2:w.reload)*(perks.reload?.65:1),duration=Math.max(.001,last+Math.max(reload,recovery)),sustained=damage*w.mag/duration;
 const rows=[['IMPACT',num(w.damage*near)+(w.pellets>1?' × '+w.pellets:'')],['SPLASH',w.splash?num(w.splash)+' / '+num(w.blast)+' m':w.payload==='rocket'||w.payload==='airburst'||w.payload==='skip'?num(w.blast)+' m':'—'],['CYCLE',w.mode==='burst'?num(w.burstGap)+'s / '+num(cycle)+'s':num(cycle)+' s'],['LOADED',num(w.mag)+' / '+loaded+' pulls'],['RELOAD',w.feedMode==='recovery'?'.60s / round':w.feedMode==='individual'?'INSERT / INTERRUPT':num(w.reload*(perks.reload?.65:1))+' s'],['SUSTAINED',w.feedMode==='recovery'?'RELEASE TO LOAD':Math.round(sustained)+' DPS']];
 const delta=Math.abs((a.damage*a.pellets+a.splash)-damage)>.01?'<p class="build-delta">'+num(a.damage*a.pellets+a.splash)+' → '+num(damage)+' damage / cartridge</p>':'';
 return `<div class="build-mode">${firingLabel(w)}${w.volley>1?' · '+w.volley+' AT ONCE':''}</div><div class="weapon-stats">${rows.map(([label,value])=>`<div class="weapon-stat"><small>${label}</small><strong>${value}</strong></div>`).join('')}</div>${delta}<p class="ballistic-note" title="Ideal single-target damage before headshots; includes reload and cycle recovery">${w.payload.toUpperCase()}${w.penetration.length>1?' · PIERCES '+w.penetration.length:''}${w.arc?' · 2 ARC JUMPS':''}${w.slamfire?' · RELEASE TO SETTLE':''}</p>`;
}
function header(s){return `<header class="shop-header"><div class="shop-heading"><small>FRAGONY / WEAPON SYSTEMS</small><h1>${s.practice?'PRACTICE WORKBENCH':s.inspect?'ARSENAL':'LOADOUT'}</h1>${s.inspect||s.practice?'':`<span>PREPARE FOR ROUND ${s.round+1}</span>`}</div>${s.inspect||s.practice?'':`<strong class="shop-credits">${s.credits}<small> CR</small></strong>`}<div class="shop-actions"><button id="inspect-weapon">INSPECT GUN</button><button id="savequit">${s.practice?'RETURN TO PRACTICE':s.inspect?'MAIN MENU':'SAVE & EXIT'}</button>${s.inspect||s.practice?'':`<button class="shop-start" id="nextmatch">PLAY ROUND ${s.round+1}</button>`}</div></header>`}
function fittedPanel(s){const w=s.weapons[s.gun],b=s.builds[s.gun]||{slots:{},owned:[]};return `<aside class="owned-loadout"><div class="owned-heading"><h2>${s.inspect?'PREVIEW BUILD':'EQUIPPED'}</h2><span>${gameplayCount(b)} / 3 PARTS</span></div><div class="owned-gun-title"><b>${w.name}</b><button id="reset-build">STOCK RESET</button></div>${statsHTML(w,s.gun,s.builds,s.preview||s.builds,s.perks)}<div class="owned-slots">${Object.entries(WEAPON_SLOTS[s.gun]).map(([slot,items])=>{const available=slot==='optic'||s.practice||s.inspect?items:items.filter(a=>b.owned.includes(a.id));return `<label><span>${SLOT_LABELS[slot]}</span><select data-owned-slot="${slot}" aria-label="${w.name} ${SLOT_LABELS[slot]}"><option value="">Standard</option>${available.map(a=>`<option value="${a.id}" ${b.slots[slot]===a.id?'selected':''}>${a.name}${slot==='optic'?' · FREE':''}</option>`).join('')}</select>${b.slots[slot]?`<small>${esc(attachment(s.gun,b.slots[slot])?.desc||'Free sight preference')}</small>`:''}</label>`}).join('')}</div>${s.inspect||s.practice?'':`<div class="owned-gear">${Object.entries(EQUIPMENT).map(([key,items])=>`<label><span>${key==='throwable'?'Grenade ×'+(s.perks.frags?4:2):'Killstreak'}</span><select data-owned-gear="${key}">${items.filter(a=>s.equipment.owned.includes(a.id)).map(a=>`<option value="${a.id}" ${s.equipment[key]===a.id?'selected':''}>${a.name}</option>`).join('')}</select></label>`).join('')}</div>`}</aside>`}
function card(s,g,a,offer=null){const b=s.builds[g]||{owned:[],slots:{}},fit=b.slots[a.slot]===a.id,bought=b.owned.includes(a.id)||a.slot==='optic',preview=s.inspect||s.practice,price=offer?.price??a.price,pinned=s.pinnedOffer?.gun===g&&s.pinnedOffer?.id===a.id,affordable=preview||bought||s.credits>=price;
 return `<article class="attachment-card ${fit?'fitted':''}"><small>${s.weapons[g].name} / ${SLOT_LABELS[a.slot]}${offer?.starter?' / STARTER PRICE':''}</small><button class="offer" ${s.inspect?`data-preview-part="${g}:${a.id}"`:`data-shop-part="${g}:${a.id}"`} ${fit||!affordable?'disabled':''}><span class="offer-top"><b>${a.name}</b><em class="offer-cost ${!affordable?'short-cash':''}">${fit?'FITTED':preview?'TRY':bought?'FIT FREE':price+' CR'}</em></span><span class="offer-body">${a.reticle?reticleIcon(a.reticle):''}<span>${esc(a.desc||a.zoom+'× · free preference')}</span></span></button>${!preview&&!bought?`<div class="part-actions"><button data-part-preview="${g}:${a.id}">COMPARE</button><button data-pin="${g}:${a.id}" aria-pressed="${pinned}">${pinned?'PINNED ★':'PIN FOR NEXT SHOP'}</button></div>`:''}</article>`;
}
function simpleOffer(a,attrs,credits,owned=false){return `<button class="offer" ${attrs} ${owned||credits<a.price?'disabled':''}><span class="offer-top"><b>${a.name}</b><em class="offer-cost ${!owned&&credits<a.price?'short-cash':''}">${owned?'OWNED':a.price+' CR'}</em></span><span class="offer-body">${esc(a.desc)}</span></button>`}
function replacement(s){if(!s.pending)return'';const a=attachment(s.pending.gun,s.pending.id),b=s.builds[s.pending.gun];return `<div class="attachment-replace"><div><small>THREE GAMEPLAY PARTS MAXIMUM</small><h2>MAKE ROOM FOR ${a.name.toUpperCase()}</h2><p>Choose the fitted part to remove. It stays owned; the swap is free.</p>${Object.entries(b.slots).filter(([slot])=>slot!=='optic'&&slot!==a.slot).map(([slot,id])=>`<button data-replace-slot="${slot}"><small>${SLOT_LABELS[slot]}</small>${attachment(s.pending.gun,id).name}</button>`).join('')}<button id="cancel-part">CANCEL</button></div></div>`}
export function loadoutHTML(s){
 s={...s,owned:WEAPON_ORDER.filter(g=>s.owned.includes(g))};const selected=s.gun,all=s.inspect||s.practice,guns=all?WEAPON_ORDER:s.owned;
 const weaponNav=`<nav class="armory-weapons" aria-label="Weapons">${guns.map(g=>`<div><button data-gun="${g}" class="${g===selected?'selected':''}" aria-pressed="${g===selected}">${gunIcon(g)}<span>${s.weapons[g].name}</span></button>${!all?`<button data-start="${g}" aria-label="Start with ${s.weapons[g].name}" class="start-star ${s.starting===g?'active':''}">${s.starting===g?'★':'☆'}</button>`:''}</div>`).join('')}</nav>`;
 const parts=all?`<nav class="armory-tabs" aria-label="Attachment categories">${Object.keys(WEAPON_SLOTS[selected]).map(slot=>`<button data-catalog-slot="${slot}" class="${slot===s.slot?'selected':''}">${SLOT_LABELS[slot]}</button>`).join('')}</nav><div class="attachment-grid">${(WEAPON_SLOTS[selected][s.slot]||[]).map(a=>card(s,selected,a)).join('')}</div>`:`<div class="shop-offer-heading"><h2>ATTACHMENTS</h2><span>FIT THREE · MAKE IT YOURS</span></div><div class="attachment-grid">${s.offers.attachments.map(o=>card(s,o.gun,attachment(o.gun,o.id),o)).join('')||'<p>All attachment stock is owned.</p>'}</div>`;
 const basics=all?'':`<section class="armory-supplies"><div><h2>WEAPONS</h2>${s.offers.weapons.map(g=>simpleOffer({...s.weapons[g],price:s.weapons[g].price||220},`data-shop-gun="${g}"`,s.credits,s.owned.includes(g))).join('')||'<p>All weapons owned.</p>'}</div><div><h2>PERKS</h2>${s.offers.perks.map(id=>simpleOffer(s.upgrades.find(a=>a.id===id),`data-buy="${id}"`,s.credits,!!s.perks[id])).join('')}</div><div><h2>EQUIPMENT</h2>${s.offers.equipment.map(key=>{const [type,id]=key.split(':'),a=type==='perk'?s.upgrades.find(a=>a.id===id):EQUIPMENT[type].find(a=>a.id===id);return simpleOffer(a,type==='perk'?`data-buy="${id}"`:`data-gear="${key}"`,s.credits,type==='perk'?!!s.perks[id]:s.equipment.owned.includes(id))}).join('')}</div></section>`;
 return `<div class="shop-shell armory-shell">${header(s)}${weaponNav}<main class="armory-board"><section class="armory-stock">${parts}${s.preview?`<div class="compare-panel"><small>PREVIEW · ${s.weapons[s.gun].name}</small>${statsHTML(s.weapons[s.gun],s.gun,s.builds,s.preview,s.perks)}<button id="clear-preview">CLOSE COMPARISON</button></div>`:''}${basics}</section>${fittedPanel(s)}</main><footer class="shop-status"><span id="loadout-status" role="status" tabindex="-1">${esc(s.message||'One action · one ammunition · one feed · one handling. Choose three.')}</span><span>${s.practice?'ALL PARTS FREE IN PRACTICE':s.inspect?'PREVIEW ONLY · YOUR RUN IS UNCHANGED':'Owned parts swap free · Sights are free'}</span></footer>${replacement(s)}</div>`;
}
